SELECT gen_random_uuid()::text, 'formula', '$S = VI^* = P + jQ$', 'Complex Power and the Power Triangle', '$\mathbf{S} = \mathbf{V}\mathbf{I}^* = P + jQ,\qquad |S| = VI = \sqrt{P^2 + Q^2}$', '$\text{VA}$', 'Real and reactive power in one complex number; its magnitude is the apparent power.', '[{"symbol":"$\\mathbf{V}, \\mathbf{I}$","meaning":"RMS phasors","unit":"$\\text{V}$"},{"symbol":"$P$","meaning":"real power","unit":"$\\text{W}$"},{"symbol":"$Q$","meaning":"reactive power (+ inductive)","unit":"$\\text{var}$"}]'::jsonb, 'Use the CONJUGATE of the current. Complex power is conserved: add the S of every load to get the source''s.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'ac power (real, reactive, apparent)' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
