SELECT gen_random_uuid()::text, 'formula', '$C = \frac{Q_C}{\omega V^2}$', 'Correcting Capacitance', '$C = \frac{Q_C}{\omega V^2}\ (\text{single phase});\qquad C_{\text{per phase}} = \frac{Q_C/3}{\omega V_{\text{phase}}^2}$', '$\text{F}$', 'The capacitance that supplies a required kvar.', '[{"symbol":"$Q_C$","meaning":"capacitor reactive power needed","unit":"$\\text{var}$"},{"symbol":"$V$","meaning":"voltage across the capacitor","unit":"$\\text{V}$"},{"symbol":"$\\omega$","meaning":"2πf","unit":"$\\text{rad/s}$"}]'::jsonb, 'Delta-connected capacitors see line voltage and need a third of the wye capacitance for the same kvar.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'power factor correction' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
