SELECT gen_random_uuid()::text, 'formula', '$Z_L = Z_{th}^*$', 'Maximum Power Transfer in AC', '$Z_L = Z_{th}^*:\ P_{\max} = \frac{|V_{th}|^2}{4R_{th}};\qquad \text{resistive load only: } R_L = |Z_{th}|$', '$\text{W}$', 'The load that takes the most power from an ac source: the conjugate of its impedance cancels the reactance.', '[{"symbol":"$V_{th}$","meaning":"Thévenin voltage, RMS","unit":"$\\text{V}$"},{"symbol":"$Z_{th} = R_{th} + jX_{th}$","meaning":"Thévenin impedance","unit":"$\\Omega$"}]'::jsonb, 'If the load must be a pure resistance, it should equal |Z_th|, and it gets less than the conjugate-match maximum.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'maximum power in ac' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
