SELECT gen_random_uuid()::text, 'formula', '$BW = \frac{\omega_0}{Q}$', 'Bandwidth and Half-Power Frequencies', '$BW = \omega_2 - \omega_1 = \frac{\omega_0}{Q},\qquad \omega_0 = \sqrt{\omega_1\omega_2};\qquad \text{series: } BW = \frac{R}{L}$', '$\text{rad/s}$', 'The width of a resonance peak between the points where power falls to half.', '[{"symbol":"$\\omega_1, \\omega_2$","meaning":"half-power (−3 dB) frequencies","unit":"$\\text{rad/s}$"},{"symbol":"$Q$","meaning":"quality factor","unit":null}]'::jsonb, 'ω₀ is the GEOMETRIC mean of ω₁ and ω₂, not the average (they are nearly equal only for high Q).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'series and parallel resonance' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
