SELECT gen_random_uuid()::text, 'formula', '$Q_p = \omega_0RC$', 'Parallel Resonance', '$\text{ideal: } \omega_0 = \frac{1}{\sqrt{LC}},\ Q_p = \frac{R}{\omega_0L} = \omega_0RC;\qquad \text{coil with resistance } r: \omega_0 = \sqrt{\frac{1}{LC} - \frac{r^2}{L^2}}$', NULL, 'Resonance of L and C in parallel: the impedance is a maximum and the source current a minimum.', '[{"symbol":"$R$","meaning":"parallel resistance","unit":"$\\Omega$"},{"symbol":"$r$","meaning":"resistance of the coil","unit":"$\\Omega$"}]'::jsonb, 'Parallel Q is R/(ω₀L), the inverse of the series form. The tank''s circulating current is Q times the line current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'series and parallel resonance' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
