SELECT gen_random_uuid()::text, 'formula', '$v_1 = L_1\frac{di_1}{dt} \pm M\frac{di_2}{dt}$', 'Mutually Coupled Coil Voltages', '$v_1 = L_1\frac{di_1}{dt} \pm M\frac{di_2}{dt};\qquad \text{phasor: } \mathbf{V}_1 = j\omega L_1\mathbf{I}_1 \pm j\omega M\mathbf{I}_2$', '$\text{V}$', 'Each coil''s voltage includes a term from the other coil''s changing current.', '[{"symbol":"$M$","meaning":"mutual inductance","unit":"$\\text{H}$"},{"symbol":"$i_1, i_2$","meaning":"coil currents","unit":"$\\text{A}$"}]'::jsonb, 'Dot convention: + if both currents enter (or both leave) the dotted ends, − otherwise.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'magnetically coupled circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
