SELECT gen_random_uuid()::text, 'formula', '$W = \tfrac12L_1i_1^2 + \tfrac12L_2i_2^2 \pm Mi_1i_2$', 'Energy in Coupled Coils', '$W = \tfrac12L_1i_1^2 + \tfrac12L_2i_2^2 \pm Mi_1i_2$', '$\text{J}$', 'The magnetic energy stored in two coupled coils.', '[{"symbol":"$L_1, L_2$","meaning":"self-inductances","unit":"$\\text{H}$"},{"symbol":"$M$","meaning":"mutual inductance","unit":"$\\text{H}$"}]'::jsonb, 'Because W can never be negative, M ≤ √(L₁L₂): the coupling coefficient k is at most 1.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'magnetically coupled circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
