SELECT gen_random_uuid()::text, 'formula', '$Z_{in} = Z_1 + \frac{\omega^2M^2}{Z_2 + Z_L}$', 'Reflected Impedance of Coupled Coils', '$Z_{in} = Z_1 + \frac{\omega^2M^2}{Z_2 + Z_L}$', '$\Omega$', 'The impedance seen at the primary of a linear (air-core) transformer.', '[{"symbol":"$Z_1, Z_2$","meaning":"primary and secondary self-impedances (jωL plus winding resistance)","unit":"$\\Omega$"},{"symbol":"$Z_L$","meaning":"load on the secondary","unit":"$\\Omega$"}]'::jsonb, 'A capacitive secondary reflects as inductive and vice versa: the reflected term divides by the secondary impedance.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'magnetically coupled circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
