SELECT gen_random_uuid()::text, 'formula', '$V_L = \sqrt3V_p,\ I_L = \sqrt3I_p$', 'Wye and Delta Line Relations', '$\text{wye: } \mathbf{V}_{L} = \sqrt3\mathbf{V}_p\angle30^\circ,\ I_L = I_p;\qquad \text{delta: } V_L = V_p,\ \mathbf{I}_L = \sqrt3\mathbf{I}_p\angle{-30^\circ}$', NULL, 'How line and phase quantities relate in balanced wye and delta connections (abc sequence).', '[{"symbol":"$V_p, I_p$","meaning":"phase voltage and current","unit":"$\\text{V}$"},{"symbol":"$V_L, I_L$","meaning":"line voltage and current","unit":"$\\text{A}$"}]'::jsonb, 'A balanced delta load equals a wye of one-third its impedance: Z_Y = Z_Δ/3. Solve one phase of the wye equivalent.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'balanced three-phase systems' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
