SELECT gen_random_uuid()::text, 'formula', '$V_N = \frac{\sum V_kY_k}{\sum Y_k}$', 'Millman''s Theorem (Neutral Shift)', '$\mathbf{V}_{N''N} = \frac{\mathbf{V}_aY_a + \mathbf{V}_bY_b + \mathbf{V}_cY_c}{Y_a + Y_b + Y_c + Y_N}$', '$\text{V}$', 'The voltage of an unbalanced wye load''s star point when it isn''t tied to the source neutral.', '[{"symbol":"$\\mathbf{V}_k$","meaning":"source phase voltages","unit":"$\\text{V}$"},{"symbol":"$Y_k$","meaning":"load admittances (Y_N = 0 with no neutral wire)","unit":"$\\text{S}$"}]'::jsonb, 'With a solid neutral the shift is zero and each phase is solved alone; the neutral then carries I_a + I_b + I_c.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'unbalanced three-phase systems' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$P = W_1 + W_2$', 'Two-Wattmeter Method', '$P = W_1 + W_2,\qquad \tan\theta = \sqrt3\frac{W_2 - W_1}{W_1 + W_2}\ (\text{balanced})$', '$\text{W}$', 'Total power of any three-wire load from two wattmeters; for a balanced load, also its power factor.', '[{"symbol":"$W_1, W_2$","meaning":"wattmeter readings (W₂ the larger for a lagging load)","unit":"$\\text{W}$"}]'::jsonb, 'At pf 0.5 one meter reads zero; below 0.5 it reads negative (reverse its connection and subtract).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'three-phase power measurement' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
