SELECT gen_random_uuid()::text, 'formula', '$V_{a1} = \frac13(V_a + aV_b + a^2V_c)$', 'Symmetrical Components Transformation', '$\mathbf{V}_{a0} = \tfrac13(\mathbf{V}_a + \mathbf{V}_b + \mathbf{V}_c),\ \mathbf{V}_{a1} = \tfrac13(\mathbf{V}_a + a\mathbf{V}_b + a^2\mathbf{V}_c),\ \mathbf{V}_{a2} = \tfrac13(\mathbf{V}_a + a^2\mathbf{V}_b + a\mathbf{V}_c);\ a = 1\angle120^\circ$', '$\text{V}$', 'Any unbalanced three-phase set as zero-, positive- and negative-sequence sets.', '[{"symbol":"$V_a, V_b, V_c$","meaning":"unbalanced phase voltages (phasors)","unit":"$\\text{V}$"},{"symbol":"$a$","meaning":"operator 1∠120°","unit":null}]'::jsonb, 'Back again: V_a = V₀ + V₁ + V₂, V_b = V₀ + a²V₁ + aV₂. A wye with no neutral has no zero-sequence current.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'symmetrical components' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
