SELECT gen_random_uuid()::text, 'formula', '$f(t) = a_0 + \sum(a_n\cos n\omega t + b_n\sin n\omega t)$', 'Fourier Series', '$a_0 = \frac1T\int_0^T f\,dt,\quad a_n = \frac2T\int_0^T f\cos n\omega t\,dt,\quad b_n = \frac2T\int_0^T f\sin n\omega t\,dt$', NULL, 'A periodic wave as a dc term plus harmonics.', '[{"symbol":"$T$","meaning":"period","unit":"$\\text{s}$"},{"symbol":"$\\omega$","meaning":"2π/T","unit":"$\\text{rad/s}$"}]'::jsonb, 'Even functions have only cosines, odd only sines; half-wave symmetry leaves only odd harmonics. A square wave: (4V/π)(sin ωt + sin 3ωt/3 + …).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'non-sinusoidal waves and fourier' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
