SELECT gen_random_uuid()::text, 'formula', '$V_{rms} = \sqrt{V_0^2 + \sum V_n^2}$', 'RMS and Power of Non-Sinusoidal Waves', '$V_{rms} = \sqrt{V_0^2 + V_1^2 + V_2^2 + \cdots};\qquad P = V_0I_0 + \sum V_nI_n\cos\theta_n$', '$\text{V}$', 'The RMS of a wave with harmonics, and the power it delivers: each frequency counts on its own.', '[{"symbol":"$V_0$","meaning":"dc component","unit":"$\\text{V}$"},{"symbol":"$V_n, I_n$","meaning":"RMS values of each harmonic","unit":"$\\text{V}$"}]'::jsonb, 'Power only comes from voltage and current of the SAME frequency; cross terms average to zero.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'non-sinusoidal waves and fourier' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
