SELECT gen_random_uuid()::text, 'formula', '$THD = \frac{\sqrt{\sum_{n\ge2}V_n^2}}{V_1}$', 'Total Harmonic Distortion', '$THD = \frac{\sqrt{V_2^2 + V_3^2 + \cdots}}{V_1}$', NULL, 'How far a wave is from a pure sine.', '[{"symbol":"$V_1$","meaning":"fundamental (RMS)","unit":"$\\text{V}$"},{"symbol":"$V_n$","meaning":"harmonic n (RMS)","unit":"$\\text{V}$"}]'::jsonb, 'With THD known, V_rms = V₁√(1 + THD²). Non-linear loads (drives, rectifiers) cause harmonic currents.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'non-sinusoidal waves and fourier' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
