SELECT gen_random_uuid()::text, 'formula', '$\mathbf{V} = \mathbf{z}\mathbf{I}$', 'Two-Port z and y Parameters', '$\begin{bmatrix}V_1\\V_2\end{bmatrix} = \begin{bmatrix}z_{11} & z_{12}\\z_{21} & z_{22}\end{bmatrix}\begin{bmatrix}I_1\\I_2\end{bmatrix},\qquad \mathbf{y} = \mathbf{z}^{-1}$', NULL, 'A two-port described by its terminal equations; each parameter is measured with the other port open (z) or shorted (y).', '[{"symbol":"$z_{ij}$","meaning":"open-circuit impedance parameters","unit":"$\\Omega$"},{"symbol":"$y_{ij}$","meaning":"short-circuit admittance parameters","unit":"$\\text{S}$"}]'::jsonb, 'Reciprocal (passive, no dependent sources): z₁₂ = z₂₁. Series two-ports add z; parallel ones add y.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'two-port networks' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
