SELECT gen_random_uuid()::text, 'formula', '$V_1 = AV_2 + BI_2$', 'Transmission (ABCD) Parameters', '$\begin{bmatrix}V_1\\I_1\end{bmatrix} = \begin{bmatrix}A & B\\C & D\end{bmatrix}\begin{bmatrix}V_2\\I_2\end{bmatrix},\qquad AD - BC = 1 \text{ (reciprocal)}$', NULL, 'Sending-end quantities from receiving-end ones; cascaded two-ports multiply their ABCD matrices.', '[{"symbol":"$A, D$","meaning":"voltage and current ratios (dimensionless)","unit":null},{"symbol":"$B$","meaning":"transfer impedance","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"transfer admittance","unit":"$\\text{S}$"}]'::jsonb, 'I₂ is taken flowing OUT of port 2. A series Z: [1 Z; 0 1]; a shunt Y: [1 0; Y 1].', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'two-port networks' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
