SELECT gen_random_uuid()::text, 'formula', '$Z_L = sL,\ Z_C = \frac{1}{sC}$', 's-Domain Element Models', '$Z_R = R,\quad Z_L = sL \text{ with a source } Li(0^-),\quad Z_C = \frac{1}{sC} \text{ with a source } \frac{v(0^-)}{s}$', '$\Omega$', 'Circuit elements in the Laplace domain, with their initial conditions as extra sources.', '[{"symbol":"$s$","meaning":"complex frequency","unit":"$\\text{1/s}$"},{"symbol":"$i(0^-), v(0^-)$","meaning":"initial inductor current and capacitor voltage","unit":null}]'::jsonb, 'With these models, nodal and mesh analysis solve transients algebraically; invert by partial fractions.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'laplace in circuits' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
