SELECT gen_random_uuid()::text, 'formula', '$f(\infty) = \lim_{s\to0}sF(s)$', 'Initial and Final Value Theorems', '$f(0^+) = \lim_{s\to\infty}sF(s),\qquad f(\infty) = \lim_{s\to0}sF(s)$', NULL, 'A response''s start and end values straight from its transform, without inverting it.', '[{"symbol":"$F(s)$","meaning":"Laplace transform of f(t)","unit":null}]'::jsonb, 'The final value theorem holds only if every pole of sF(s) is in the left half-plane (no oscillation or growth).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'laplace in circuits' AND s."active"), NULL, true, 'PENDING', now(), now()
