SELECT gen_random_uuid()::text, 'formula', '$f_c = \frac{1}{2\pi RC}$', 'First-Order RC Filters', '$\text{low-pass: } H = \frac{1}{1 + j\omega RC};\quad \text{high-pass: } H = \frac{j\omega RC}{1 + j\omega RC};\quad f_c = \frac{1}{2\pi RC},\ |H(f_c)| = \frac{1}{\sqrt2}\ (-3\ \text{dB})$', '$\text{Hz}$', 'The simplest filters and their cutoff frequency.', '[{"symbol":"$R$","meaning":"resistance","unit":"$\\Omega$"},{"symbol":"$C$","meaning":"capacitance","unit":"$\\text{F}$"}]'::jsonb, 'Gain in dB is 20 log|H|. Past the cutoff a first-order filter falls 20 dB per decade (6 dB per octave).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE' AND s."normKey" = 'filters' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electric Circuits 2' AND t."subject" = 'EE'
